CREATE FUNCTION touch_updated() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=clock_timestamp(); RETURN NEW; END $$;
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, owner text NOT NULL, outcome text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX projects_code_ci ON projects(lower(code));
CREATE TABLE indicators(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, unit text NOT NULL DEFAULT 'unreviewed', aggregation text NOT NULL DEFAULT 'unreviewed' CHECK(aggregation IN ('unreviewed','sum','weighted-rate','snapshot')), definition text NOT NULL DEFAULT '', method text NOT NULL DEFAULT '', approved_by text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX indicators_code_ci ON indicators(lower(code));
CREATE TABLE periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, starts_on date, ends_on date, due_on date, state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')), closed_by text, closure_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(starts_on IS NULL OR ends_on>=starts_on), CHECK(ends_on IS NULL OR due_on>=ends_on));
CREATE UNIQUE INDEX periods_code_ci ON periods(lower(code));
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, indicator_id uuid NOT NULL REFERENCES indicators, period_id uuid NOT NULL REFERENCES periods, owner text NOT NULL, target numeric CHECK(target>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,indicator_id,period_id));
CREATE TABLE cells(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, assignment_id uuid NOT NULL REFERENCES assignments, location text NOT NULL, dimensions jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(dimensions)='object'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,location,dimensions));
CREATE TABLE imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), digest text NOT NULL UNIQUE, file_name text NOT NULL, original_base64 text NOT NULL, mapping jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE result_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cell_id uuid NOT NULL REFERENCES cells, version integer NOT NULL CHECK(version>0), value numeric NOT NULL CHECK(value>=0), denominator numeric CHECK(denominator>0), evidence text NOT NULL DEFAULT '', reporter text NOT NULL, observed_on date, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','rejected')), reviewed_by text, review_note text, import_id uuid REFERENCES imports, source_row jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cell_id,version), CHECK(denominator IS NULL OR value<=denominator), CHECK(state='pending' OR (length(trim(reviewed_by))>0 AND length(trim(review_note))>0)), CHECK(state!='accepted' OR length(trim(evidence))>0));
CREATE TABLE actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, assignment_id uuid NOT NULL REFERENCES assignments, description text NOT NULL, owner text NOT NULL, due_on date NOT NULL, state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','done')), evidence text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(state!='done' OR length(trim(evidence))>0));
CREATE TABLE notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, note text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor text NOT NULL, operation text NOT NULL, record_id uuid, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_import BEFORE UPDATE OR DELETE ON imports FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_note BEFORE UPDATE OR DELETE ON notes FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION review_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Result history cannot be deleted'; END IF;
 IF OLD.state!='pending' OR NEW.state='pending' OR (to_jsonb(NEW)-'state'-'reviewed_by'-'review_note'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'reviewed_by'-'review_note'-'updated_at') THEN RAISE EXCEPTION 'Only a pending result review can change; record a new version for corrections'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER result_review_only BEFORE UPDATE OR DELETE ON result_versions FOR EACH ROW EXECUTE FUNCTION review_only();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['projects','indicators','periods','assignments','cells','result_versions','actions'] LOOP EXECUTE format('CREATE TRIGGER updated BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated()',t); END LOOP;
FOREACH t IN ARRAY ARRAY['projects','indicators','periods','assignments','cells','result_versions','actions','imports','notes','audit'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t); END LOOP; END $$;
CREATE VIEW v_current_results AS SELECT DISTINCT ON(c.id) c.id AS cell_id,c.code,c.assignment_id,c.location,c.dimensions,r.id AS result_id,r.version,r.value,r.denominator,r.evidence,r.reporter,r.observed_on,r.state,r.reviewed_by,r.review_note,r.updated_at FROM cells c JOIN result_versions r ON r.cell_id=c.id ORDER BY c.id,r.version DESC;
CREATE VIEW v_reporting_desk AS
SELECT a.id,a.project_id,a.indicator_id,a.period_id,p.code AS project,p.name AS project_name,i.code AS indicator,i.name AS indicator_name,i.aggregation,i.unit,q.code AS period,q.starts_on,q.ends_on,q.due_on,q.state AS period_state,a.owner,a.target,
 count(r.cell_id)::integer AS cells,count(r.cell_id) FILTER(WHERE r.state='accepted')::integer AS accepted,count(r.cell_id) FILTER(WHERE r.state='pending')::integer AS pending,count(r.cell_id) FILTER(WHERE r.state='rejected')::integer AS rejected,
 CASE WHEN count(r.cell_id)>0 AND bool_and(r.state='accepted') THEN CASE WHEN i.aggregation='sum' THEN sum(r.value) WHEN i.aggregation='weighted-rate' AND bool_and(r.denominator IS NOT NULL) THEN round(100*sum(r.value)/nullif(sum(r.denominator),0),2) WHEN i.aggregation='snapshot' AND count(r.cell_id)=1 THEN max(r.value) END END AS actual,
 max(r.updated_at) AS last_result_at
FROM assignments a JOIN projects p ON p.id=a.project_id JOIN indicators i ON i.id=a.indicator_id JOIN periods q ON q.id=a.period_id LEFT JOIN v_current_results r ON r.assignment_id=a.id GROUP BY a.id,p.id,i.id,q.id;
CREATE VIEW v_attention AS
SELECT id,project,indicator,period,owner,due_on,
 CASE WHEN cells=0 THEN 'missing submission' WHEN pending>0 THEN 'awaiting review' WHEN rejected>0 THEN 'rejected result' WHEN actual IS NULL THEN 'aggregation review' WHEN target IS NOT NULL AND actual<target THEN 'below target' ELSE 'ready' END AS issue,
 CASE WHEN due_on<current_date AND period_state='open' THEN current_date-due_on ELSE 0 END AS days_overdue
FROM v_reporting_desk WHERE period_state='open';
CREATE VIEW v_compliance AS
SELECT a.id,a.project,a.indicator,a.period,'measurement definition'::text AS rule,'Define the measure, unit and aggregation before reporting'::text AS finding FROM v_reporting_desk a JOIN indicators i ON i.id=a.indicator_id WHERE i.aggregation='unreviewed' OR trim(i.definition)='' OR trim(i.method)='' OR trim(i.approved_by)='' OR i.unit='unreviewed'
UNION ALL SELECT id,project,indicator,period,'reporting calendar','Review reporting dates and due date' FROM v_reporting_desk WHERE starts_on IS NULL OR ends_on IS NULL OR due_on IS NULL
UNION ALL SELECT d.id,d.project,d.indicator,d.period,'evidence traceability','One or more current results lack source evidence or observation date' FROM v_reporting_desk d WHERE EXISTS(SELECT 1 FROM v_current_results r WHERE r.assignment_id=d.id AND (trim(r.evidence)='' OR r.observed_on IS NULL))
UNION ALL SELECT d.id,d.project,d.indicator,d.period,'weighted denominator','Rate results need numerator and denominator, not averaged percentages' FROM v_reporting_desk d WHERE d.aggregation='weighted-rate' AND EXISTS(SELECT 1 FROM v_current_results r WHERE r.assignment_id=d.id AND r.denominator IS NULL)
UNION ALL SELECT id,project,indicator,period,'completeness','Missing, pending, rejected or nonaggregable results prevent period closure' FROM v_reporting_desk WHERE actual IS NULL
UNION ALL SELECT id,project,indicator,period,'target context','No period target recorded; do not describe performance against plan' FROM v_reporting_desk WHERE target IS NULL;
REVOKE ALL ON v_current_results,v_reporting_desk,v_attention,v_compliance FROM PUBLIC;
